const rows = $input.all().map(item => item.json);

// Get environment from webhook query, default QA
let requestedEnvironment = 'QA';

try {
  requestedEnvironment =
    $('API 01 - GET health-status').first().json.query?.environment || 'QA';
} catch (e) {
  requestedEnvironment = 'QA';
}

// Only use requested environment
const environmentRows = rows.filter(
  row => (row['Environment'] || 'QA') === requestedEnvironment
);

// Convert timestamp into something sortable
function timestampValue(value) {
  if (!value) return 0;

  // "2026-09-10 15:28:49" -> valid ISO-like format
  const normalized = String(value).replace(' ', 'T');
  const parsed = new Date(normalized).getTime();

  return Number.isNaN(parsed) ? 0 : parsed;
}

// Find latest record for every service
const latestByService = {};

for (const row of environmentRows) {
  const serviceName = row['Service Name'];

  if (!serviceName) continue;

  const existing = latestByService[serviceName];

  if (
    !existing ||
    timestampValue(row['Timestamp']) >
      timestampValue(existing['Timestamp'])
  ) {
    latestByService[serviceName] = row;
  }
}

const latestRows = Object.values(latestByService);

// Convert sheet health status into dashboard status
function mapStatus(row) {
  const healthStatus = String(row['Health Status'] || '').toUpperCase();
  const functionalValidation = String(
    row['Functional Validation'] || ''
  ).toUpperCase();

  // A functional assertion failure wins even when the HTTP call returned 200.
  if (functionalValidation === 'FAIL') {
    return 'FUNCTIONAL_FAILURE';
  }

  if (healthStatus === 'DOWN' || healthStatus === 'FAILED') {
    return 'DOWN';
  }

  // The monitor emits DEGRADED (older exports emitted SLOW).
  if (healthStatus === 'DEGRADED' || healthStatus === 'SLOW') {
    return 'SLOW';
  }

  // UP means the HTTP check passed. Requiring functionalValidation === 'PASS'
  // here left every service without an expectedText (NOT_APPLICABLE) UNKNOWN.
  if (healthStatus === 'UP' || healthStatus === 'HEALTHY') {
    return 'HEALTHY';
  }

  return 'UNKNOWN';
}

const services = latestRows.map(row => ({
  name: row['Service Name'],
  application: row['Application'] || 'VWO',
  environment: row['Environment'] || requestedEnvironment,
  checkType: row['Check Type'] || 'HTTP',
  endpoint: row['Endpoint'] || '',
  httpStatus: Number(row['HTTP Status'] || 0),
  responseTimeMs: Number(row['Response Time Ms'] || 0),
  responseTimeThresholdMs: Number(
    row['Response Time Threshold Ms'] || 3000
  ),
  status: mapStatus(row),
  functionalValidation: row['Functional Validation'] || '',
  retryCount: Number(row['Retry Count'] || 0),
  errorMessage: row['Error Message'] || '',
  critical: Boolean(row['Critical']),
  lastCheckedAt: row['Timestamp'] || ''
}));

const healthyServices = services.filter(
  service => service.status === 'HEALTHY'
).length;

const failedServices = services.filter(
  service =>
    service.status === 'DOWN' ||
    service.status === 'FUNCTIONAL_FAILURE'
).length;

const slowServices = services.filter(
  service => service.status === 'SLOW'
).length;

const averageResponseTimeMs =
  services.length > 0
    ? Math.round(
        services.reduce(
          (sum, service) => sum + service.responseTimeMs,
          0
        ) / services.length
      )
    : 0;

const latestTimestamp =
  latestRows.length > 0
    ? latestRows
        .map(row => row['Timestamp'])
        .filter(Boolean)
        .sort()
        .at(-1) || ''
    : '';

// Only a *critical* failure should take the whole application DOWN; a single
// non-critical service failing is a degradation, not an outage.
const criticalFailures = latestRows.filter((row) => {
  const state = mapStatus(row);

  return (
    (state === 'DOWN' || state === 'FUNCTIONAL_FAILURE') &&
    (row['Critical'] === true ||
      String(row['Critical']).toLowerCase() === 'true')
  );
}).length;

let overallStatus = 'UNKNOWN';

if (services.length > 0) {
  if (criticalFailures > 0) {
    overallStatus = 'DOWN';
  } else if (failedServices > 0 || slowServices > 0) {
    overallStatus = 'DEGRADED';
  } else {
    overallStatus = 'HEALTHY';
  }
}

// Availability across the whole window. Dividing the current snapshot by the
// service count made one failure look like 80% uptime.
const totalChecks = environmentRows.length;

const unavailableChecks = environmentRows.filter((row) => {
  const state = mapStatus(row);

  return state === 'DOWN' || state === 'FUNCTIONAL_FAILURE';
}).length;

const uptimePct =
  totalChecks > 0
    ? Number(
        (((totalChecks - unavailableChecks) / totalChecks) * 100).toFixed(2)
      )
    : 0;

return [
  {
    json: {
      summary: {
        overallStatus,
        servicesMonitored: services.length,
        healthyServices,
        failedServices,
        activeIncidents: 0,
        averageResponseTimeMs,
        uptimePct,
        lastCheckedAt: latestTimestamp,
        environment: requestedEnvironment
      },
      services
    }
  }
];

const rows = $input.all().map(item => item.json);

// Read requested environment from webhook
let requestedEnvironment = 'QA';

try {
  requestedEnvironment =
    $('API 02 - GET health-checks').first().json.query?.environment || 'QA';
} catch (e) {
  requestedEnvironment = 'QA';
}

// Filter by environment
const filteredRows = rows.filter(
  row => (row['Environment'] || 'QA') === requestedEnvironment
);

// Convert Google Sheet rows into clean dashboard/API objects
const healthChecks = filteredRows.map(row => ({
  timestamp: row['Timestamp'] || '',
  application: row['Application'] || 'VWO',
  environment: row['Environment'] || requestedEnvironment,

  serviceName: row['Service Name'] || '',
  checkType: row['Check Type'] || 'HTTP',
  endpoint: row['Endpoint'] || '',

  httpStatus: Number(row['HTTP Status'] || 0),
  responseTimeMs: Number(row['Response Time Ms'] || 0),
  responseTimeThresholdMs: Number(
    row['Response Time Threshold Ms'] || 3000
  ),

  healthStatus: row['Health Status'] || 'UNKNOWN',
  functionalValidation: row['Functional Validation'] || '',

  retryCount: Number(row['Retry Count'] || 0),
  errorMessage: row['Error Message'] || '',

  workflowExecutionId: String(
    row['Workflow Execution ID'] || ''
  ),

  critical:
    row['Critical'] === true ||
    String(row['Critical']).toLowerCase() === 'true'
}));

// Newest checks first
healthChecks.sort((a, b) =>
  String(b.timestamp).localeCompare(String(a.timestamp))
);

return [
  {
    json: {
      environment: requestedEnvironment,
      count: healthChecks.length,
      healthChecks
    }
  }
];

const rows = $input.all().map(item => item.json);

// Read requested environment from webhook.
// Default to QA if no environment is provided.
let requestedEnvironment = 'QA';

try {
  requestedEnvironment =
    $('API 03 - GET logs').first().json.query?.environment || 'QA';
} catch (e) {
  requestedEnvironment = 'QA';
}

// Filter records by environment
const filteredRows = rows.filter(
  row => (row['Environment'] || 'QA') === requestedEnvironment
);

// Convert health-check history into dashboard log entries
const logs = filteredRows.map(row => {
  const healthStatus = String(
    row['Health Status'] || 'UNKNOWN'
  ).toUpperCase();

  const functionalValidation = String(
    row['Functional Validation'] || ''
  ).toUpperCase();

  // Determine log level
  let level = 'INFO';

  if (
    healthStatus === 'DOWN' ||
    healthStatus === 'FAILED' ||
    functionalValidation === 'FAIL'
  ) {
    level = 'ERROR';
  } else if (
    healthStatus === 'SLOW' ||
    Number(row['Response Time Ms'] || 0) >
      Number(row['Response Time Threshold Ms'] || 3000)
  ) {
    level = 'WARN';
  }

  // Build readable message
  let message = `${row['Service Name'] || 'Unknown Service'} health check`;

  if (healthStatus === 'UP') {
    message += ` passed (${row['HTTP Status'] || 0})`;
  } else {
    message += ` returned ${healthStatus}`;
  }

  if (row['Error Message']) {
    message += ` - ${row['Error Message']}`;
  }

  return {
    timestamp: row['Timestamp'] || '',
    level,
    application: row['Application'] || 'VWO',
    environment: row['Environment'] || requestedEnvironment,
    serviceName: row['Service Name'] || '',
    checkType: row['Check Type'] || 'HTTP',
    endpoint: row['Endpoint'] || '',
    httpStatus: Number(row['HTTP Status'] || 0),
    responseTimeMs: Number(row['Response Time Ms'] || 0),
    healthStatus,
    functionalValidation:
      row['Functional Validation'] || '',
    retryCount: Number(row['Retry Count'] || 0),
    message,
    errorMessage: row['Error Message'] || '',
    workflowExecutionId: String(
      row['Workflow Execution ID'] || ''
    ),
    critical:
      row['Critical'] === true ||
      String(row['Critical']).toLowerCase() === 'true'
  };
});

// Newest logs first
logs.sort((a, b) =>
  String(b.timestamp).localeCompare(String(a.timestamp))
);

return [
  {
    json: {
      environment: requestedEnvironment,
      count: logs.length,
      logs
    }
  }
];

const rows = $input.all().map(item => item.json);

// Get environment from API 04 webhook
let requestedEnvironment = 'QA';

try {
  requestedEnvironment =
    $('API 04 - GET response-times').first().json.query?.environment || 'QA';
} catch (e) {
  requestedEnvironment = 'QA';
}

// Filter by requested environment
const filteredRows = rows.filter(
  row => (row['Environment'] || 'QA') === requestedEnvironment
);

// Convert sheet rows into response-time metrics
const responseTimes = filteredRows.map(row => {
  const responseTimeMs = Number(row['Response Time Ms'] || 0);
  const thresholdMs = Number(
    row['Response Time Threshold Ms'] || 3000
  );

  let status = 'HEALTHY';

  if (
    String(row['Health Status'] || '').toUpperCase() === 'DOWN' ||
    String(row['Health Status'] || '').toUpperCase() === 'FAILED'
  ) {
    status = 'DOWN';
  } else if (responseTimeMs > thresholdMs) {
    status = 'SLOW';
  }

  return {
    timestamp: row['Timestamp'] || '',
    application: row['Application'] || 'VWO',
    environment: row['Environment'] || requestedEnvironment,
    serviceName: row['Service Name'] || '',
    endpoint: row['Endpoint'] || '',
    responseTimeMs,
    thresholdMs,
    httpStatus: Number(row['HTTP Status'] || 0),
    status,
    workflowExecutionId: String(
      row['Workflow Execution ID'] || ''
    )
  };
});

// Newest first
responseTimes.sort((a, b) =>
  String(b.timestamp).localeCompare(String(a.timestamp))
);

// Calculate useful chart summary
const values = responseTimes
  .map(item => item.responseTimeMs)
  .filter(value => Number.isFinite(value));

const averageResponseTimeMs =
  values.length > 0
    ? Math.round(
        values.reduce((sum, value) => sum + value, 0) /
        values.length
      )
    : 0;

const minResponseTimeMs =
  values.length > 0 ? Math.min(...values) : 0;

const maxResponseTimeMs =
  values.length > 0 ? Math.max(...values) : 0;

return [
  {
    json: {
      environment: requestedEnvironment,
      count: responseTimes.length,
      summary: {
        averageResponseTimeMs,
        minResponseTimeMs,
        maxResponseTimeMs
      },
      responseTimes
    }
  }
];

const rows = $input.all().map(item => item.json);

// Read environment from webhook, default QA
let requestedEnvironment = 'QA';

try {
  requestedEnvironment =
    $('API 05 - GET uptime').first().json.query?.environment || 'QA';
} catch (e) {
  requestedEnvironment = 'QA';
}

// Prefer OVERALL / ALL_SERVICES rows.
// If environment-specific rows exist, allow those too.
const relevantRows = rows.filter(row => {
  const env = String(row['Environment'] || '').toUpperCase();
  const service = String(row['Service Name'] || '').toUpperCase();

  return (
    env === requestedEnvironment.toUpperCase() ||
    env === 'OVERALL'
  ) && (
    service === 'ALL_SERVICES' ||
    service === ''
  );
});

// Map into clean uptime objects
const uptime = relevantRows.map(row => ({
  date: row['Date'] || '',
  application: row['Application'] || 'VWO',
  environment: row['Environment'] || requestedEnvironment,
  serviceName: row['Service Name'] || 'ALL_SERVICES',
  totalChecks: Number(row['Total Checks'] || 0),
  failedChecks: Number(row['Failed Checks'] || 0),
  availabilityPercentage: Number(
    row['Availability Percentage'] || 0
  ),
  updatedAt: row['Updated At'] || ''
}));

// Sort oldest -> newest for charting
uptime.sort((a, b) =>
  String(a.date).localeCompare(String(b.date))
);

// Latest availability summary
const latest = uptime.length > 0
  ? uptime[uptime.length - 1]
  : null;

return [
  {
    json: {
      environment: requestedEnvironment,
      count: uptime.length,
      summary: {
        currentUptimePct: latest
          ? latest.availabilityPercentage
          : 0,
        totalChecks: latest
          ? latest.totalChecks
          : 0,
        failedChecks: latest
          ? latest.failedChecks
          : 0,
        lastUpdatedAt: latest
          ? latest.updatedAt
          : ''
      },
      uptime
    }
  }
];

const rows = $input.all()
  .map(item => item.json)
  .filter(row =>
    row &&
    Object.keys(row).length > 0 &&
    (
      row['Incident ID'] ||
      row['Service Name'] ||
      row['Downtime Start']
    )
  );

// Get environment from API 06 webhook
let requestedEnvironment = 'QA';
let requestedIncidentId = '';

try {
  const query =
    $('API 06 - GET incidents').first().json.query || {};

  requestedEnvironment = query.environment || 'QA';
  requestedIncidentId = query.id || '';
} catch (e) {
  requestedEnvironment = 'QA';
}

// Filter incidents by environment
let filteredRows = rows.filter(row => {
  const environment =
    row['Environment'] || requestedEnvironment;

  return environment === requestedEnvironment;
});

// If ?id=INC-xxx was supplied, return only that incident
if (requestedIncidentId) {
  filteredRows = filteredRows.filter(
    row =>
      String(row['Incident ID'] || '') ===
      String(requestedIncidentId)
  );
}

// Map Google Sheet rows into clean incident objects
// Retry timeline entries previously had no timestamp; derive them from the
// incident start plus the configured retry delays.
function shiftSheetTime(value, seconds) {
  const match = String(value || '').match(
    /^(\d{4})-(\d{2})-(\d{2})[ T](\d{1,2}):(\d{2}):(\d{2})/
  );

  if (!match) {
    return '';
  }

  const base = new Date(
    Number(match[1]),
    Number(match[2]) - 1,
    Number(match[3]),
    Number(match[4]),
    Number(match[5]),
    Number(match[6])
  );

  base.setSeconds(base.getSeconds() + seconds);

  const pad = (n) => String(n).padStart(2, '0');

  return (
    base.getFullYear() +
    '-' +
    pad(base.getMonth() + 1) +
    '-' +
    pad(base.getDate()) +
    ' ' +
    pad(base.getHours()) +
    ':' +
    pad(base.getMinutes()) +
    ':' +
    pad(base.getSeconds())
  );
}

const incidents = filteredRows.map(row => {
  const status = String(
    row['Status'] || 'OPEN'
  ).toUpperCase();

  const retryCount = Number(
    row['Retry Count'] || 0
  );

  const downtimeSeconds = Number(
    row['Downtime Seconds'] || 0
  );

  const timeline = [];

  if (row['Downtime Start']) {
    timeline.push({
      type: 'INCIDENT_STARTED',
      timestamp: row['Downtime Start'],
      message: 'Service failure detected'
    });
  }

  if (retryCount >= 1) {
    timeline.push({
      type: 'RETRY',
      attempt: 2,
      delaySeconds: 20,
      timestamp: shiftSheetTime(row['Downtime Start'], 22),
      message: 'Retry attempt after 20 seconds'
    });
  }

  if (retryCount >= 2) {
    timeline.push({
      type: 'RETRY',
      attempt: 3,
      delaySeconds: 30,
      timestamp: shiftSheetTime(row['Downtime Start'], 54),
      message: 'Final retry attempt after 30 seconds'
    });
  }

  if (row['Recovery Time']) {
    timeline.push({
      type: 'RECOVERED',
      timestamp: row['Recovery Time'],
      message: 'Service recovered'
    });
  }

  if (row['Resolved At']) {
    timeline.push({
      type: 'RESOLVED',
      timestamp: row['Resolved At'],
      message: row['Resolved By']
        ? `Incident resolved by ${row['Resolved By']}`
        : 'Incident resolved'
    });
  }

  return {
    incidentId: row['Incident ID'] || '',
    application: row['Application'] || 'VWO',
    environment:
      row['Environment'] || requestedEnvironment,
    serviceName: row['Service Name'] || '',
    endpoint: row['Endpoint'] || '',
    status,
    severity: row['Severity'] || 'UNKNOWN',
    downtimeStart: row['Downtime Start'] || '',
    recoveryTime: row['Recovery Time'] || '',
    downtimeSeconds,
    retryCount,
    httpStatus: Number(
      row['HTTP Status'] || 0
    ),
    responseTimeMs: Number(
      row['Response Time Ms'] || 0
    ),
    failureReason: row['Failure Reason'] || '',
    httpResponse: row['HTTP Response'] || '',
    workflowExecutionId: String(
      row['Workflow Execution ID'] || ''
    ),
    resolvedAt: row['Resolved At'] || '',
    resolvedBy: row['Resolved By'] || '',
    timeline
  };
});

// Newest incidents first
incidents.sort((a, b) =>
  String(b.downtimeStart)
    .localeCompare(String(a.downtimeStart))
);

const activeIncidents = incidents.filter(
  incident =>
    incident.status === 'OPEN' ||
    incident.status === 'ACTIVE' ||
    incident.status === 'INVESTIGATING'
).length;

return [
  {
    json: {
      environment: requestedEnvironment,
      count: incidents.length,
      activeIncidents,
      incidents
    }
  }
];

const rows = $input.all()
  .map(item => item.json)
  .filter(row =>
    row &&
    Object.keys(row).length > 0 &&
    (
      row['Incident ID'] ||
      row['Service Name'] ||
      row['Downtime Start']
    )
  );

// Get environment from API 07 webhook
let requestedEnvironment = 'QA';

try {
  requestedEnvironment =
    $('API 07 - GET retry-history').first().json.query?.environment || 'QA';
} catch (e) {
  requestedEnvironment = 'QA';
}

// Filter incidents by environment
const filteredRows = rows.filter(row =>
  (row['Environment'] || requestedEnvironment) === requestedEnvironment
);

const retryHistory = [];

for (const row of filteredRows) {
  const retryCount = Number(row['Retry Count'] || 0);

  // Retry #1 = attempt 2 after initial request
  if (retryCount >= 1) {
    retryHistory.push({
      incidentId: row['Incident ID'] || '',
      application: row['Application'] || 'VWO',
      environment: row['Environment'] || requestedEnvironment,
      serviceName: row['Service Name'] || '',
      endpoint: row['Endpoint'] || '',

      attempt: 2,
      retryNumber: 1,
      delaySeconds: 20,

      status: row['Status'] || '',
      severity: row['Severity'] || '',

      httpStatus: Number(row['HTTP Status'] || 0),
      responseTimeMs: Number(row['Response Time Ms'] || 0),

      failureReason: row['Failure Reason'] || '',
      workflowExecutionId: String(
        row['Workflow Execution ID'] || ''
      ),

      incidentStartedAt: row['Downtime Start'] || ''
    });
  }

  // Retry #2 = attempt 3 / final retry
  if (retryCount >= 2) {
    retryHistory.push({
      incidentId: row['Incident ID'] || '',
      application: row['Application'] || 'VWO',
      environment: row['Environment'] || requestedEnvironment,
      serviceName: row['Service Name'] || '',
      endpoint: row['Endpoint'] || '',

      attempt: 3,
      retryNumber: 2,
      delaySeconds: 30,

      status: row['Status'] || '',
      severity: row['Severity'] || '',

      httpStatus: Number(row['HTTP Status'] || 0),
      responseTimeMs: Number(row['Response Time Ms'] || 0),

      failureReason: row['Failure Reason'] || '',
      workflowExecutionId: String(
        row['Workflow Execution ID'] || ''
      ),

      incidentStartedAt: row['Downtime Start'] || ''
    });
  }
}

// Newest incidents first
retryHistory.sort((a, b) =>
  String(b.incidentStartedAt)
    .localeCompare(String(a.incidentStartedAt))
);

return [
  {
    json: {
      environment: requestedEnvironment,
      count: retryHistory.length,
      retryHistory
    }
  }
];

// Get the incoming POST request
const input = $input.first()?.json || {};

// Read environment from request body/query.
// Default to QA if nothing was supplied.
const environment =
  input.body?.environment ||
  input.query?.environment ||
  input.environment ||
  'QA';

const triggeredAt = new Date().toISOString();

return [
  {
    json: {
      ok: true,
      triggeredAt,
      environment,
      executionId: String($execution.id),
      services: [],
      message:
        'Health check request accepted. Monitoring workflow will be triggered.'
    }
  }
];

const rows = $input.all()
  .map(item => item.json)
  .filter(row =>
    row &&
    Object.keys(row).length > 0 &&
    row['Key']
  );

// Default configuration
const settings = {
  responseTimeThresholdMs: 3000,
  retryAttempts: 3,
  retryDelaysSeconds: [20, 30],
  checkIntervalMinutes: 5,
  environments: ['QA', 'Staging', 'Production']
};

// Convert Google Sheet Key/Value rows into settings
for (const row of rows) {
  const key = String(row['Key'] || '').trim();
  const rawValue = row['Value'];

  if (!key) {
    continue;
  }

  switch (key) {
    case 'responseTimeThresholdMs':
      settings.responseTimeThresholdMs =
        Number(rawValue) || 3000;
      break;

    case 'retryAttempts':
      settings.retryAttempts =
        Number(rawValue) || 3;
      break;

    case 'retryDelaysSeconds':
      if (Array.isArray(rawValue)) {
        settings.retryDelaysSeconds =
          rawValue.map(Number);
      } else {
        settings.retryDelaysSeconds =
          String(rawValue)
            .split(',')
            .map(value => Number(value.trim()))
            .filter(value => Number.isFinite(value));
      }

      if (settings.retryDelaysSeconds.length === 0) {
        settings.retryDelaysSeconds = [20, 30];
      }
      break;

    case 'checkIntervalMinutes':
      settings.checkIntervalMinutes =
        Number(rawValue) || 5;
      break;

    case 'environments':
      if (Array.isArray(rawValue)) {
        settings.environments = rawValue;
      } else {
        const environments =
          String(rawValue)
            .split(',')
            .map(value => value.trim())
            .filter(Boolean);

        if (environments.length > 0) {
          settings.environments = environments;
        }
      }
      break;
  }
}

// The monitor workflow stores the retry ladder as retryCount / retryDelayMs
// (+ retryDelayMs2). Mirror those so GET /settings reflects what is monitored.
const flat = {};

for (const row of rows) {
  const flatKey = String(row['Key'] || '').trim();

  if (flatKey) {
    flat[flatKey] = row['Value'];
  }
}

if (flat.retryCount !== undefined && flat.retryAttempts === undefined) {
  settings.retryAttempts = (Number(flat.retryCount) || 0) + 1;
}

const delayLadder = [flat.retryDelayMs, flat.retryDelayMs2]
  .map((value) => Number(value))
  .filter((value) => Number.isFinite(value) && value > 0);

if (delayLadder.length > 0) {
  settings.retryDelaysSeconds = delayLadder.map((ms) =>
    Math.round(ms / 1000)
  );
}

return [
  {
    json: {
      settings
    }
  }
];

// Get incoming POST webhook data
const input = $input.first().json;

// Webhook POST payload is inside "body"
const body = input.body ?? input;

// Define the settings your API is allowed to update
const allowedSettings = [
  'environment',
  'application',
  'responseTimeThresholdMs',
  'retryCount',
  'retryDelayMs',
  'retryDelayMs2',
  'retryAttempts',
  'retryDelaysSeconds',
  'checkIntervalMinutes',
];

// Convert supplied settings into rows
const rows = [];

for (const key of allowedSettings) {
  if (
    Object.prototype.hasOwnProperty.call(body, key) &&
    body[key] !== undefined &&
    body[key] !== null &&
    body[key] !== ''
  ) {
    const rawValue = body[key];

    rows.push({
      json: {
        setting: key,
        value: Array.isArray(rawValue)
          ? rawValue.join(',')
          : rawValue,
      },
    });
  }
}

// Nothing valid supplied
if (rows.length === 0) {
  return [
    {
      json: {
        _noSettings: true,
        message: 'No valid settings were supplied.',
        receivedBody: body,
      },
    },
  ];
}

return rows;

