const items = $input.all();

const updatedSettings = items.map(item => ({
  key: item.json.Key,
  value: item.json.Value,
}));

return [
  {
    json: {
      success: true,
      message: `${updatedSettings.length} settings updated successfully`,
      updatedCount: updatedSettings.length,
      settings: updatedSettings,
    },
  },
];

const body = $json.body || $json;

const incidentId =
  body.incidentId ||
  body["Incident ID"];

if (!incidentId) {
  throw new Error("incidentId is required");
}

return {
  json: {
    incidentId,
    resolvedBy: body.resolvedBy || "manual",
    resolutionNotes: body.resolutionNotes || ""
  }
};

const x = $json;

const incidentId = x["Incident ID"];
const downtimeStartRaw = x["Downtime Start"];

if (!incidentId) {
  throw new Error("Incident ID not found");
}

if (!downtimeStartRaw) {
  throw new Error(
    `Downtime Start not found for incident ${incidentId}`
  );
}

// Parse format:
// YYYY-MM-DD H:mm:ss
// or
// YYYY-MM-DD HH:mm:ss

function parseSheetDateTime(value) {
  const str = String(value).trim();

  const match = str.match(
    /^(\d{4})-(\d{2})-(\d{2})\s+(\d{1,2}):(\d{2}):(\d{2})$/
  );

  if (!match) {
    throw new Error(`Unsupported Downtime Start format: ${str}`);
  }

  const [, year, month, day, hour, minute, second] = match;

  return new Date(
    Number(year),
    Number(month) - 1,
    Number(day),
    Number(hour),
    Number(minute),
    Number(second)
  );
}

const downtimeStart = parseSheetDateTime(downtimeStartRaw);

if (Number.isNaN(downtimeStart.getTime())) {
  throw new Error(
    `Invalid Downtime Start: ${downtimeStartRaw}`
  );
}

const recoveryDate = new Date();

const downtimeSeconds = Math.max(
  0,
  Math.floor(
    (recoveryDate.getTime() - downtimeStart.getTime()) / 1000
  )
);

function formatDateTime(date) {
  const pad = (n) => String(n).padStart(2, "0");

  return (
    `${date.getFullYear()}-` +
    `${pad(date.getMonth() + 1)}-` +
    `${pad(date.getDate())} ` +
    `${pad(date.getHours())}:` +
    `${pad(date.getMinutes())}:` +
    `${pad(date.getSeconds())}`
  );
}

return {
  json: {
    ...x,

    "Status": "RESOLVED",

    "Recovery Time":
      formatDateTime(recoveryDate),

    "Downtime Seconds":
      downtimeSeconds,

    "Workflow Execution ID":
      String($execution.id)
  }
};
